// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import {KeelSealValidation} from "@keel/keel-hold/libraries/KeelSealValidation.sol";
import {IKeelHold} from "@keel/keel-hold/interfaces/IKeelHold.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {KeelUriEscape} from "@keel/keel-kernel/libraries/KeelUriEscape.sol";
import {IKeelRawTokenURIBuilder} from "./interfaces/IKeelRawTokenURIBuilder.sol";

/// @title KEEL raw percent tokenURI builder
/// @notice Streams a prevalidated percent-carried JSON document directly from
/// raw KeelHold bytes. The HTML animation and binary child resources keep only
/// the encoding their own data-URI boundary requires; the complete metadata is
/// never Base64-encoded again.
contract KeelRawTokenURIBuilder is IKeelRawTokenURIBuilder {
    bytes32 private constant MEDIA_TYPE_HASH = keccak256("application/vnd.keel.token-uri-raw-percent-fragment");
    bytes private constant URI_PREFIX = "data:application/json;charset=utf-8,";
    bytes private constant ANIMATION_MARKER = '"animation_url":"data:text/html;charset=utf-8,';
    bytes private constant SCHEMA_MARKER = "\",\"keel_schema\":\"";
    uint256 private constant MAX_DEPTH = 8;
    uint256 private constant DATA_URI_LITERAL_MASK = 0x0000000000000000000000000000000047fffffe87ffffff2fffff1200000000;

    IKeelHold public immutable keelHold;

    error InvalidStore();
    error InvalidFragment();
    error InvalidEnvelope();
    error FragmentTooDeep();
    error FragmentLengthMismatch();
    error FragmentDigestMismatch();

    /// @notice Checks the one-time platform registration at collection setup.
    function requireRegistration(bytes32 objectId) external view returns (bool compact) {
        KeelSealValidation.requireHoldHarness(address(keelHold), address(this), objectId);
        return true;
    }

    constructor(address keelHold_) {
        if (keelHold_.code.length == 0) revert InvalidStore();
        keelHold = IKeelHold(keelHold_);
    }

    /// @notice Encoding negotiation for collections using the shared fragment API.
    function rawTokenURI() external pure returns (bool) { return true; }

    function percentEscape(bytes memory value) external pure returns (bytes memory) {
        return KeelUriEscape.escape(value);
    }

    /// @notice The same integrity-bound context tail prepared by the SDK.
    function contextURI(bytes memory contextJSON) public pure returns (bytes memory) {
        return KeelUriEscape.escape(bytes.concat(
            bytes('<script>(()=>{try{const v="'), bytes(Base64.encodeURL(contextJSON)),
            bytes('",b=v.replace(/-/g,"+").replace(/_/g,"/")+"=".repeat((4-v.length%4)%4),j=atob(b),c=Object.freeze(JSON.parse(j)),o=Object.freeze({json:j,digest:"'),
            bytes(Strings.toHexString(uint256(sha256(contextJSON)), 32)), bytes('",byteLength:'),
            bytes(Strings.toString(contextJSON.length)),
            bytes('});Object.defineProperty(globalThis,"__KEEL_CONTEXT__",{value:c,enumerable:true,writable:false,configurable:false});Object.defineProperty(globalThis,"__KEEL_ONCHAIN_CONTEXT__",{value:o,enumerable:true,writable:false,configurable:false})}catch(e){document.documentElement.dataset.keelContext="failed";throw e}})()</script>')
        ));
    }

    /// @notice Raw JSON compatibility; ordinary tokenURI uses the direct-copy path.
    function harnessInlineURIWithContext(bytes32 objectId, bytes32 digest, bytes calldata contextJSON)
        external view returns (string memory)
    {
        return string(bytes.concat(bytes("data:text/html;charset=utf-8,"), preEncodedTokenJSONMiddle(objectId, digest), contextURI(contextJSON)));
    }

    function preEncodedTokenURIFragmentValid(bytes32 objectId, bytes32 digest) external view returns (bool) {
        return preparedTokenURIFragmentValid(objectId, digest);
    }

    /// @notice Only the small live metadata envelope is escaped at read time.
    /// Every shell, module and artwork fragment is copied from its stored bytes.
    function preEncodedTokenURI(bytes32 objectId, bytes32 digest, bytes calldata rawPrefix, bytes calldata rawSuffix)
        external view returns (string memory)
    {
        // escape() itself guarantees canonical percent bytes. Validate the small
        // envelope boundaries directly, without scanning and decoding the large
        // already-prepared image payload for a second time.
        bytes memory prefix = rawPrefix;
        bytes memory suffix = rawSuffix;
        if (!_rawEnvelopeValid(prefix, suffix)) revert InvalidEnvelope();
        return _copyPreparedTokenURI(objectId, digest, bytes32(0), KeelUriEscape.escape(prefix), KeelUriEscape.escape(suffix));
    }

    /// @notice Reads independently revisioned fragment roots in immutable order.
    /// @dev Sources are resolved by the caller's KEEL artifact handles. Each
    ///      source remains sealed, SHA-256 checked, and depth bounded.
    ///      Registration is enforced by publication policy and consumer setup.
    ///      This does not select a new shell or reinterpret resource contents.
    function preEncodedTokenURIFragments(
        bytes32[] calldata objectIds,
        bytes32[] calldata digests,
        bytes calldata rawPrefix,
        bytes calldata rawSuffix
    ) external view returns (string memory) {
        uint256 count = objectIds.length;
        if (count == 0 || count > 128 || count != digests.length) revert InvalidFragment();
        if (!_rawEnvelopeValid(rawPrefix, rawSuffix)) revert InvalidEnvelope();
        bytes memory prefix = KeelUriEscape.escape(rawPrefix);
        bytes memory suffix = KeelUriEscape.escape(rawSuffix);
        uint256 outputLength = URI_PREFIX.length + prefix.length + suffix.length;
        uint64[] memory lengths = new uint64[](count);
        for (uint256 i; i < count; ++i) {
            if (!preparedTokenURIFragmentValid(objectIds[i], digests[i])) revert InvalidFragment();
            lengths[i] = keelHold.getObject(objectIds[i]).byteLength;
            outputLength += lengths[i];
        }
        bytes memory returnBuffer = new bytes(outputLength + 32);
        bytes memory output;
        assembly ("memory-safe") {
            output := add(returnBuffer, 32)
            mstore(output, outputLength)
        }
        uint256 cursor;
        _copy(output, cursor, URI_PREFIX);
        cursor += URI_PREFIX.length;
        _copy(output, cursor, prefix);
        cursor += prefix.length;
        for (uint256 i; i < count; ++i) {
            uint256 start = cursor;
            cursor = _copyObject(objectIds[i], output, cursor, 0);
            if (cursor - start != lengths[i]) revert FragmentLengthMismatch();
            if (_sha256Range(output, start, lengths[i]) != digests[i]) revert FragmentDigestMismatch();
        }
        _copy(output, cursor, suffix);
        cursor += suffix.length;
        if (cursor != outputLength) revert FragmentLengthMismatch();
        assembly ("memory-safe") {
            mstore(returnBuffer, 32)
            return(returnBuffer, add(64, and(add(outputLength, 31), not(31))))
        }
    }

    /// @notice Copies separately revisioned prepared raster/SVG-Base64 image and viewer roots.
    /// @dev No media payload is encoded or decoded at read time. The image is itself a prepared raw-percent fragment.
    function preEncodedTokenURIFragmentsWithImage(
        bytes32[] calldata objectIds,
        bytes32[] calldata digests,
        bytes32 imageObjectId,
        bytes32 imageDigest,
        bytes calldata rawPrefix,
        bytes calldata rawSuffix
    ) external view returns (string memory) {
        uint256 count = objectIds.length;
        if (
            count == 0 || count >= 128 || count != digests.length
                || !preparedTokenURIFragmentValid(imageObjectId, imageDigest)
        ) revert InvalidFragment();
        bytes memory prefix = rawPrefix;
        if (
            prefix.length == 0 || prefix[0] != bytes1("{") || !_endsWith(prefix, bytes('"image":"'))
                || !_rawEnvelopeValid(bytes('{"animation_url":"data:text/html;charset=utf-8,'), rawSuffix)
        ) {
            revert InvalidEnvelope();
        }
        prefix = KeelUriEscape.escape(prefix);
        bytes memory boundary = KeelUriEscape.escape(bytes('","animation_url":"data:text/html;charset=utf-8,'));
        bytes memory suffix = KeelUriEscape.escape(rawSuffix);
        uint64 imageLength = keelHold.getObject(imageObjectId).byteLength;
        uint256 outputLength = URI_PREFIX.length + prefix.length + imageLength + boundary.length + suffix.length;
        uint64[] memory lengths = new uint64[](count);
        for (uint256 i; i < count; ++i) {
            if (!preparedTokenURIFragmentValid(objectIds[i], digests[i])) revert InvalidFragment();
            lengths[i] = keelHold.getObject(objectIds[i]).byteLength;
            outputLength += lengths[i];
        }
        bytes memory returnBuffer = new bytes(outputLength + 32);
        bytes memory output;
        assembly ("memory-safe") {
            output := add(returnBuffer, 32)
            mstore(output, outputLength)
        }
        _copy(output, 0, URI_PREFIX);
        uint256 cursor = URI_PREFIX.length;
        _copy(output, cursor, prefix);
        cursor += prefix.length;
        uint256 imageStart = cursor;
        cursor = _copyObject(imageObjectId, output, cursor, 0);
        if (cursor - imageStart != imageLength) revert FragmentLengthMismatch();
        if (_sha256Range(output, imageStart, imageLength) != imageDigest) revert FragmentDigestMismatch();
        _copy(output, cursor, boundary);
        cursor += boundary.length;
        for (uint256 i; i < count; ++i) {
            uint256 start = cursor;
            cursor = _copyObject(objectIds[i], output, cursor, 0);
            if (cursor - start != lengths[i]) revert FragmentLengthMismatch();
            if (_sha256Range(output, start, lengths[i]) != digests[i]) revert FragmentDigestMismatch();
        }
        _copy(output, cursor, suffix);
        cursor += suffix.length;
        if (cursor != outputLength) revert FragmentLengthMismatch();
        assembly ("memory-safe") {
            mstore(returnBuffer, 32)
            return(returnBuffer, add(64, and(add(outputLength, 31), not(31))))
        }
    }

    /// @notice Copies a prepared image URI and viewer through the same KEEL
    /// fragment reader. Only the small, live envelope is encoded at read time.
    /// The caller binds the image after validating its prepared URI bytes.
    function preEncodedTokenURIWithImage(
        bytes32 objectId, bytes32 digest, bytes32 imageObjectId,
        bytes calldata rawPrefix, bytes calldata rawSuffix
    ) external view returns (string memory) {
        bytes memory prefix = rawPrefix;
        bytes memory suffix = rawSuffix;
        if (imageObjectId == bytes32(0) || prefix.length == 0 || prefix[0] != bytes1("{")
            || !_endsWith(prefix, bytes('"image":"'))
            || !_rawEnvelopeValid(bytes('{"animation_url":"data:text/html;charset=utf-8,'), suffix)) {
            revert InvalidEnvelope();
        }
        return _copyPreparedTokenURI(objectId, digest, imageObjectId, KeelUriEscape.escape(prefix), KeelUriEscape.escape(suffix));
    }

    /// @notice Optional raw JSON reads decode only the outer percent boundary.
    function preEncodedTokenJSONMiddle(bytes32 objectId, bytes32 digest) public view returns (bytes memory) {
        if (!preparedTokenURIFragmentValid(objectId, digest)) revert InvalidFragment();
        bytes memory fragment = keelHold.haulObject(objectId);
        if (sha256(fragment) != digest) revert FragmentDigestMismatch();
        return _decodePercent(fragment);
    }

    /// @notice Publication replay using the same traversal and bytes accepted by tokenURI reads.
    function validatePreparedTokenURIFragment(bytes32 objectId, bytes32 expectedDigest) external view returns (bool) {
        bytes memory fragment = _preparedFragment(objectId, expectedDigest);
        (, uint8 state) = _preparedPercentScan(fragment, 0, fragment.length, 0);
        if (state != 0) revert InvalidFragment();
        return true;
    }

    /// @notice Bounded syntax step; the validation registry alone owns cursor/carry attestations.
    /// @dev Every step independently replays exact immutable source bytes and SHA before scanning its range.
    function validatePreparedTokenURIFragmentSegment(
        bytes32 objectId,
        bytes32 expectedDigest,
        uint64 offset,
        uint32 maxBytes,
        uint8 percentState
    ) external view returns (uint64 nextOffset, uint8 nextState, bool complete) {
        bytes memory fragment = _preparedFragment(objectId, expectedDigest);
        if (maxBytes == 0 || offset >= fragment.length || percentState > 2) revert InvalidFragment();
        uint256 next;
        (next, nextState) = _preparedPercentScan(fragment, offset, maxBytes, percentState);
        nextOffset = uint64(next);
        complete = next == fragment.length;
        if (complete && nextState != 0) revert InvalidFragment();
    }

    /// @notice Returns prepared image carriage verbatim after the same exact immutable replay.
    /// @dev Consumers bind a completed image-specific publication approval before calling this reader.
    function preparedImageURI(bytes32 objectId, bytes32 digest) external view returns (string memory) {
        return string(_preparedFragment(objectId, digest));
    }

    /// @notice Bounded publication validation of a self-contained, canonical image data URI.
    /// @dev Prepared Base64 carriage is copied verbatim; this never decodes media or Base64-encodes at read time.
    ///      The existing SDK verifies the source media bytes. Percent SVG carriage is intentionally not this profile.
    function validatePreparedImageURIFragmentSegment(
        bytes32 objectId,
        bytes32 expectedDigest,
        uint64 offset,
        uint32 maxBytes,
        uint8 paddingState
    ) external view returns (uint64 nextOffset, uint8 nextState, bool complete) {
        bytes memory fragment = _preparedFragment(objectId, expectedDigest);
        uint256 headerLength = _preparedImageHeaderLength(fragment);
        if (
            maxBytes == 0 || offset >= fragment.length || paddingState > 2 || fragment.length <= headerLength
                || (fragment.length - headerLength) % 4 != 0
        ) revert InvalidFragment();
        uint256 end = uint256(offset) + maxBytes;
        if (end > fragment.length) end = fragment.length;
        uint256 start = offset == 0 ? headerLength : offset;
        if (start < headerLength || end <= start) revert InvalidFragment();
        bool valid = true;
        assembly ("memory-safe") {
            let base := add(fragment, 32)
            for { let at := start } and(valid, lt(at, end)) { at := add(at, 1) } {
                let character := byte(0, mload(add(base, at)))
                switch character
                case 61 {
                    paddingState := add(paddingState, 1)
                    valid := and(lt(paddingState, 3), gt(at, sub(mload(fragment), 3)))
                }
                default {
                    valid := and(
                        iszero(paddingState),
                        or(
                            or(and(gt(character, 64), lt(character, 91)), and(gt(character, 96), lt(character, 123))),
                            or(and(gt(character, 47), lt(character, 58)), or(eq(character, 43), eq(character, 47)))
                        )
                    )
                }
            }
        }
        if (!valid) revert InvalidFragment();
        complete = end == fragment.length;
        if (complete && paddingState != 0) {
            uint256 value = _base64Value(uint8(fragment[fragment.length - paddingState - 1]));
            if ((paddingState == 1 && (value & 3) != 0) || (paddingState == 2 && (value & 15) != 0)) {
                revert InvalidFragment();
            }
        }
        return (uint64(end), paddingState, complete);
    }

    function _preparedImageHeaderLength(bytes memory fragment) private pure returns (uint256) {
        bytes[6] memory headers = [
            bytes("data:image/png;base64,"),
            bytes("data:image/jpeg;base64,"),
            bytes("data:image/gif;base64,"),
            bytes("data:image/webp;base64,"),
            bytes("data:image/avif;base64,"),
            bytes("data:image/svg+xml;base64,")
        ];
        for (uint256 i; i < headers.length; ++i) {
            bytes memory header = headers[i];
            if (fragment.length <= header.length) continue;
            bool match_ = true;
            for (uint256 j; j < header.length; ++j) {
                if (fragment[j] != header[j]) {
                    match_ = false;
                    break;
                }
            }
            if (match_) return header.length;
        }
        revert InvalidFragment();
    }

    function _base64Value(uint8 character) private pure returns (uint256) {
        if (character >= 65 && character <= 90) return character - 65;
        if (character >= 97 && character <= 122) return character - 71;
        if (character >= 48 && character <= 57) return character + 4;
        if (character == 43) return 62;
        if (character == 47) return 63;
        revert InvalidFragment();
    }

    function _preparedFragment(bytes32 objectId, bytes32 expectedDigest) private view returns (bytes memory fragment) {
        if (!preparedTokenURIFragmentValid(objectId, expectedDigest)) revert InvalidFragment();
        IKeelHold.ObjectRecord memory root = keelHold.getObject(objectId);
        fragment = new bytes(root.byteLength);
        uint256 cursor = _copyObject(objectId, fragment, 0, 0);
        if (cursor != fragment.length) revert FragmentLengthMismatch();
        if (sha256(fragment) != expectedDigest) revert FragmentDigestMismatch();
    }

    function _preparedPercentScan(bytes memory value, uint256 offset, uint256 maxBytes, uint8 state)
        private
        pure
        returns (uint256 nextOffset, uint8 nextState)
    {
        bool valid;
        // Same literal mask and upper-hex grammar as _canonicalPercentRange.
        // Carry 1/2 means one/two upper hex digits still follow the previous percent byte.
        assembly ("memory-safe") {
            let base := add(value, 32)
            let length := mload(value)
            let endOffset := add(offset, maxBytes)
            if gt(endOffset, length) { endOffset := length }
            let cursor := add(base, offset)
            let end := add(base, endOffset)
            valid := lt(cursor, end)
            for {} and(valid, lt(cursor, end)) { cursor := add(cursor, 1) } {
                let character := byte(0, mload(cursor))
                switch state
                case 0 {
                    switch character
                    case 37 { state := 2 }
                    default { valid := and(lt(character, 128), and(shr(character, DATA_URI_LITERAL_MASK), 1)) }
                }
                default {
                    valid := or(and(gt(character, 47), lt(character, 58)), and(gt(character, 64), lt(character, 71)))
                    state := sub(state, 1)
                }
            }
            nextOffset := endOffset
            nextState := state
        }
        if (!valid) revert InvalidFragment();
    }

    function preparedTokenURIFragmentValid(bytes32 objectId, bytes32 expectedDigest) public view returns (bool) {
        if (objectId == bytes32(0) || expectedDigest == bytes32(0)) return false;
        try keelHold.getObject(objectId) returns (IKeelHold.ObjectRecord memory root) {
            return root.exists && root.byteLength != 0 && root.digest == expectedDigest
                && root.compression == IKeelHold.Compression.None && keccak256(bytes(root.mediaType)) == MEDIA_TYPE_HASH;
        } catch {
            return false;
        }
    }

    function preparedTokenURIEnvelopeValid(
        bytes32 objectId,
        bytes32 expectedDigest,
        bytes calldata encodedPrefix,
        bytes calldata encodedSuffix
    ) external view returns (bool) {
        return preparedTokenURIFragmentValid(objectId, expectedDigest) && _envelopeValid(encodedPrefix, encodedSuffix);
    }

    function preparedTokenURI(
        bytes32 objectId,
        bytes32 expectedDigest,
        bytes calldata encodedPrefix,
        bytes calldata encodedSuffix
    ) external view returns (string memory) {
        if (!_envelopeValid(encodedPrefix, encodedSuffix)) revert InvalidEnvelope();
        return _copyPreparedTokenURI(objectId, expectedDigest, bytes32(0), encodedPrefix, encodedSuffix);
    }

    function _copyPreparedTokenURI(bytes32 objectId, bytes32 expectedDigest, bytes32 imageObjectId, bytes memory encodedPrefix, bytes memory encodedSuffix)
        private view returns (string memory)
    {
        if (!preparedTokenURIFragmentValid(objectId, expectedDigest)) {
            revert InvalidFragment();
        }
        IKeelHold.ObjectRecord memory root = keelHold.getObject(objectId);
        IKeelHold.ObjectRecord memory image;
        bytes memory imageBoundary;
        if (imageObjectId != bytes32(0)) {
            image = keelHold.getObject(imageObjectId);
            if (!image.exists || image.compression != IKeelHold.Compression.None
                || keccak256(bytes(image.mediaType)) != keccak256("text/plain")) revert InvalidFragment();
            imageBoundary = KeelUriEscape.escape(bytes('","animation_url":"data:text/html;charset=utf-8,'));
        }
        uint256 outputLength = URI_PREFIX.length + encodedPrefix.length + image.byteLength
            + imageBoundary.length + root.byteLength + encodedSuffix.length;
        // Reserve the ABI offset ahead of the string and fill its final return
        // buffer directly. Both callers are external entry points: returning
        // here avoids allocating and copying the complete document again.
        bytes memory returnBuffer = new bytes(outputLength + 32);
        bytes memory output;
        assembly ("memory-safe") {
            output := add(returnBuffer, 32)
            mstore(output, outputLength)
        }
        uint256 cursor;
        _copy(output, cursor, URI_PREFIX);
        cursor += URI_PREFIX.length;
        _copy(output, cursor, encodedPrefix);
        cursor += encodedPrefix.length;
        if (imageObjectId != bytes32(0)) {
            uint256 imageStart = cursor;
            cursor = _copyObject(imageObjectId, output, cursor, 0);
            if (cursor - imageStart != image.byteLength) revert FragmentLengthMismatch();
            if (_sha256Range(output, imageStart, image.byteLength) != image.digest) revert FragmentDigestMismatch();
            _copy(output, cursor, imageBoundary);
            cursor += imageBoundary.length;
        }
        uint256 fragmentStart = cursor;
        cursor = _copyObject(objectId, output, cursor, 0);
        if (cursor - fragmentStart != root.byteLength) revert FragmentLengthMismatch();
        if (_sha256Range(output, fragmentStart, root.byteLength) != expectedDigest) revert FragmentDigestMismatch();
        _copy(output, cursor, encodedSuffix);
        cursor += encodedSuffix.length;
        if (cursor != output.length) revert FragmentLengthMismatch();
        assembly ("memory-safe") {
            mstore(returnBuffer, 32)
            return(returnBuffer, add(64, and(add(outputLength, 31), not(31))))
        }
    }

    function _envelopeValid(bytes memory encodedPrefix, bytes memory encodedSuffix) private pure returns (bool) {
        if (
            !_canonicalPercentRange(encodedPrefix, 0, encodedPrefix.length)
                || !_canonicalPercentRange(encodedSuffix, 0, encodedSuffix.length)
        ) return false;
        return _rawEnvelopeValid(_decodePercent(encodedPrefix), _decodePercent(encodedSuffix));
    }

    function _rawEnvelopeValid(bytes memory rawPrefix, bytes memory rawSuffix) private pure returns (bool) {
        if (rawPrefix.length == 0 || rawPrefix[0] != bytes1("{") || !_endsWith(rawPrefix, ANIMATION_MARKER)) {
            return false;
        }
        uint256 closingQuote;
        while (closingQuote < rawSuffix.length && rawSuffix[closingQuote] != bytes1('"')) ++closingQuote;
        return closingQuote != 0 && closingQuote < rawSuffix.length && rawSuffix[rawSuffix.length - 1] == bytes1("}")
            && _canonicalPercentRange(rawSuffix, 0, closingQuote)
            && _startsWithAt(rawSuffix, closingQuote, SCHEMA_MARKER);
    }

    function _copyObject(bytes32 objectId, bytes memory output, uint256 cursor, uint256 depth)
        private
        view
        returns (uint256)
    {
        if (depth > MAX_DEPTH) revert FragmentTooDeep();
        IKeelHold.ObjectRecord memory record = keelHold.getObject(objectId);
        if (!record.exists || record.compression != IKeelHold.Compression.None) revert InvalidFragment();
        uint256 start = cursor;
        if (record.composite) {
            bytes32[] memory parts = keelHold.getObjectPartIds(objectId, 0, record.slugCount);
            if (parts.length != record.slugCount) revert FragmentLengthMismatch();
            for (uint256 index; index < parts.length; ++index) {
                cursor = _copyObject(parts[index], output, cursor, depth + 1);
            }
        } else {
            address[] memory pointers = keelHold.getObjectSlugPointers(objectId, 0, record.slugCount);
            if (pointers.length != record.slugCount) revert FragmentLengthMismatch();
            for (uint256 index; index < pointers.length; ++index) {
                uint256 length = pointers[index].code.length;
                if (length <= 1) revert InvalidFragment();
                unchecked {
                    --length;
                }
                if (cursor + length > output.length) revert FragmentLengthMismatch();
                address pointer = pointers[index];
                assembly ("memory-safe") {
                    extcodecopy(pointer, add(add(output, 0x20), cursor), 1, length)
                }
                cursor += length;
            }
        }
        if (cursor - start != record.byteLength) revert FragmentLengthMismatch();
        return cursor;
    }

    function _decodePercent(bytes memory value) private pure returns (bytes memory output) {
        output = new bytes(value.length);
        uint256 cursor;
        for (uint256 index; index < value.length; ++index) {
            if (value[index] == bytes1("%")) {
                output[cursor++] = bytes1((_hex(value[index + 1]) << 4) | _hex(value[index + 2]));
                index += 2;
            } else {
                output[cursor++] = value[index];
            }
        }
        assembly ("memory-safe") {
            mstore(output, cursor)
        }
    }

    function _canonicalPercentRange(bytes memory value, uint256 start, uint256 length) private pure returns (bool) {
        if (length == 0 || start + length > value.length) return false;
        uint256 end = start + length;
        for (uint256 index = start; index < end; ++index) {
            uint8 character = uint8(value[index]);
            if (character == 0x25) {
                if (index + 2 >= end || !_upperHex(value[index + 1]) || !_upperHex(value[index + 2])) return false;
                index += 2;
            } else if (!_dataURILiteral(character)) {
                return false;
            }
        }
        return true;
    }

    function _dataURILiteral(uint8 value) private pure returns (bool) {
        return value < 128 && DATA_URI_LITERAL_MASK & (uint256(1) << value) != 0;
    }

    function _upperHex(bytes1 character) private pure returns (bool) {
        uint8 value = uint8(character);
        return (value >= 0x30 && value <= 0x39) || (value >= 0x41 && value <= 0x46);
    }

    function _hex(bytes1 character) private pure returns (uint8) {
        uint8 value = uint8(character);
        return value <= 0x39 ? value - 0x30 : value - 0x41 + 10;
    }

    function _endsWith(bytes memory value, bytes memory suffix) private pure returns (bool) {
        if (value.length < suffix.length) return false;
        uint256 start = value.length - suffix.length;
        for (uint256 index; index < suffix.length; ++index) {
            if (value[start + index] != suffix[index]) return false;
        }
        return true;
    }

    function _startsWithAt(bytes memory value, uint256 start, bytes memory prefix) private pure returns (bool) {
        if (start + prefix.length > value.length) return false;
        for (uint256 index; index < prefix.length; ++index) {
            if (value[start + index] != prefix[index]) return false;
        }
        return true;
    }

    function _copy(bytes memory output, uint256 cursor, bytes memory value) private pure {
        if (cursor + value.length > output.length) revert FragmentLengthMismatch();
        assembly ("memory-safe") {
            mcopy(add(add(output, 0x20), cursor), add(value, 0x20), mload(value))
        }
    }

    function _sha256Range(bytes memory data, uint256 start, uint256 length) private view returns (bytes32 digest) {
        assembly ("memory-safe") {
            let ok := staticcall(gas(), 0x02, add(add(data, 0x20), start), length, 0x00, 0x20)
            if iszero(ok) { revert(0, 0) }
            digest := mload(0x00)
        }
    }
}

