// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import {IKeelHoldSeal} from "../interfaces/IKeelHoldSeal.sol";
import {IKeelHoldHarness} from "../interfaces/IKeelHoldHarness.sol";

interface IKeelHarnessRegistration {
    function requireRegistration(bytes32 objectId) external view returns (bool compact);
}

library KeelSealValidation {
    /// @dev New canonical renderers require a Hold with the registration API.
    /// Missing or failed validation cannot silently bypass the platform policy.
    function requireHoldHarness(address hold, address renderer, bytes32 objectId) internal view {
        bytes4 selector = IKeelHoldHarness.requireHarness.selector;
        assembly ("memory-safe") {
            // Temporary calldata occupies 68 bytes at the free-memory pointer.
            // No pointer escapes, and a failed check bubbles its exact error.
            let ptr := mload(0x40)
            mstore(ptr, selector)
            mstore(add(ptr, 4), objectId)
            mstore(add(ptr, 36), renderer)
            if iszero(staticcall(gas(), hold, ptr, 68, 0, 0)) {
                let size := returndatasize()
                returndatacopy(ptr, 0, size)
                revert(ptr, size)
            }
        }
    }

    /// @dev Only the current Hold policy can authorize publication. Missing
    /// or malformed responses revert through ABI decoding, never imply free use.
    function requireSealed(address hold, bytes32 objectId) internal view {
        if (IKeelHoldSeal(hold).sealRequired(objectId)) revert IKeelHoldSeal.SealRequired(objectId);
    }
}

