// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Percent encoding for a data URI carried in JSON or quoted HTML.
/// Safe bytes retain their exact representation, including Base64 punctuation.
library KeelUriEscape {
    function escape(bytes memory input) internal pure returns (bytes memory) {
        return escapePrefixed(input, "");
    }

    function escapePrefixed(bytes memory input, bytes memory prefix) internal pure returns (bytes memory output) {
        assembly ("memory-safe") {
            function safeWord(word) -> safe {
                let high := 0x8080808080808080808080808080808080808080808080808080808080808080
                if and(word, high) { leave }
                // ASCII '('..';' and letters cover long Base64 runs. Each
                // subtraction stays within its byte using a high-bit bias.
                let ranges :=
                    and(
                        sub(or(word, high), 0x2828282828282828282828282828282828282828282828282828282828282828),
                        sub(0xbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb, word)
                    )
                let letters := or(word, 0x2020202020202020202020202020202020202020202020202020202020202020)
                ranges := or(
                    ranges,
                    and(
                        sub(or(letters, high), 0x6161616161616161616161616161616161616161616161616161616161616161),
                        sub(0xfafafafafafafafafafafafafafafafafafafafafafafafafafafafafafafafa, letters)
                    )
                )
                safe := eq(and(ranges, high), high)
            }

            let mask := 0x47fffffe87ffffff2fffff1200000000
            let start := add(input, 32)
            let end := add(start, mload(input))
            let at := start
            if iszero(mload(prefix)) {
                for {} lt(at, end) { at := add(at, 32) } {
                    if iszero(safeWord(mload(at))) { break }
                }
            }
            switch and(iszero(mload(prefix)), iszero(lt(at, end)))
            case 1 { output := input }
            default {
                output := mload(0x40)
                let write := add(output, 32)
                mcopy(write, add(prefix, 32), mload(prefix))
                write := add(write, mload(prefix))
                let digits := 0x3031323334353637383941424344454600000000000000000000000000000000
                // Grow only as bytes are written. No pessimistic 3x allocation or
                // counting pass is needed; Solidity cannot observe these buffers
                // until their final length and free-memory pointer are committed.
                for { at := start } lt(at, end) { at := add(at, 32) } {
                    let word := mload(at)
                    let count := sub(end, at)
                    if gt(count, 32) { count := 32 }
                    if safeWord(word) {
                        mcopy(write, at, count)
                        write := add(write, count)
                        continue
                    }
                    for { let i := 0 } lt(i, count) { i := add(i, 1) } {
                        let c := byte(i, word)
                        switch and(lt(c, 128), and(shr(c, mask), 1))
                        case 1 {
                            mstore8(write, c)
                            write := add(write, 1)
                        }
                        default {
                            mstore8(write, 0x25)
                            mstore8(add(write, 1), byte(shr(4, c), digits))
                            mstore8(add(write, 2), byte(and(c, 15), digits))
                            write := add(write, 3)
                        }
                    }
                }
                mstore(output, sub(write, add(output, 32)))
                mstore(write, 0)
                mstore(0x40, and(add(write, 31), not(31)))
            }
        }
    }
}
